 void Scatter(Texture2D[] textures,float density,Vector2 range,float parallax,float altitude,float offset,Vector3 center,Vector3 normal,Vector3 tangent,float width,float wallHeight,int cells,System.Random rng){if(textures==null||textures.Length==0)return;float target=cells*density;int number=(int)target+(rng.NextDouble()<target-(int)target?1:0);for(int n=0;n<number;n++){var texture=textures[rng.Next(textures.Length)];if(texture==null)continue;float height=Mathf.Lerp(range.x,range.y,(float)rng.NextDouble())*wallHeight/3;float elementWidth=height*TextureAspect(texture);if(elementWidth>width*.88f){float scale=width*.88f/elementWidth;height*=scale;elementWidth*=scale;}float x=Mathf.Lerp(-width*.5f+elementWidth*.5f+.02f,width*.5f-elementWidth*.5f-.02f,(n+.15f+(float)rng.NextDouble()*.7f)/Mathf.Max(1,number));float y=altitude>0?wallHeight*Mathf.Lerp(.62f,.84f,(float)rng.NextDouble()):height*.5f+.02f;Quad("Retro "+texture.name,center+tangent*x+Vector3.up*y+normal*offset,normal,elementWidth,height,Layer(texture,parallax));ElementCount++;unchecked{CompositionHash=CompositionHash*31+(int)(x*1000)+(int)(height*1000)+texture.width;}}}
